package dao;
import conexao.Conexao;import java.sql.*;import java.time.LocalDateTime;import modelo.*;
public class ConsultaDAO {
 public void inserir(Consulta x)throws SQLException{String sql="INSERT INTO consultas(animal_id,veterinario_id,data_hora,tratamento,observacoes,status) VALUES(?,?,?,?,?,'AGENDADA')";try(Connection c=Conexao.conectar();PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,x.getAnimal().getId());p.setInt(2,x.getVeterinario().getId());p.setTimestamp(3,Timestamp.valueOf(x.getDataHora()));p.setString(4,x.getTratamento());p.setString(5,x.getObservacoes());p.executeUpdate();}}
 public Consulta buscarMaisRecentePorAnimal(String nome)throws SQLException{String sql="SELECT c.*,a.nome an,a.tipo,a.raca,a.idade,a.tutor_id,t.nome tn,t.cpf,t.telefone,t.endereco,u.id uid,u.nome vn,u.login,u.senha,v.crmv FROM consultas c JOIN animais a ON a.id=c.animal_id JOIN tutores t ON t.id=a.tutor_id JOIN veterinarios v ON v.id=c.veterinario_id JOIN usuarios u ON u.id=v.usuario_id WHERE LOWER(a.nome)=LOWER(?) ORDER BY c.data_hora DESC LIMIT 1";try(Connection cn=Conexao.conectar();PreparedStatement p=cn.prepareStatement(sql)){p.setString(1,nome);try(ResultSet r=p.executeQuery()){if(!r.next())return null;Tutor t=new Tutor(r.getInt("tutor_id"),r.getString("tn"),r.getString("cpf"),r.getString("telefone"),r.getString("endereco"));Animal a=new Animal(r.getInt("animal_id"),r.getString("an"),r.getString("tipo"),r.getString("raca"),r.getInt("idade"),t);Veterinario v=new Veterinario(r.getInt("uid"),r.getString("vn"),r.getString("login"),r.getString("senha"),r.getString("crmv"));return new Consulta(r.getInt("id"),a,v,r.getTimestamp("data_hora").toLocalDateTime(),r.getString("tratamento"),r.getString("observacoes"));}}}
 public void atualizarAtendimento(int id,String tratamento,String observacoes)throws SQLException{String sql="UPDATE consultas SET tratamento=?,observacoes=?,status='REALIZADA' WHERE id=?";try(Connection c=Conexao.conectar();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,tratamento);p.setString(2,observacoes);p.setInt(3,id);p.executeUpdate();}}
 public int contar()throws SQLException{try(Connection c=Conexao.conectar();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM consultas")){r.next();return r.getInt(1);}}
}
